#include "rbtree.h"

#include <stdlib.h>

/* ------------------------------------------------------------------------
 * Allocation seam.
 *
 * Every allocation in this file goes through these two wrappers, never
 * through malloc/free directly. HW2 replaces the bodies with a
 * fault-injecting allocator; keeping the seam here means that change never
 * has to touch the tree code itself.
 * --------------------------------------------------------------------- */

static void *rb_malloc(size_t n)
{
    return malloc(n);
}

static void rb_free(void *p)
{
    free(p);
}

/* The node struct and the color enum arrive in M1. For now the tree carries
 * only what rb_create/rb_size/rb_destroy need. */
struct rbtree {
    rb_value_free_fn value_free;
    size_t           count;
};

rbtree_t *rb_create(rb_value_free_fn value_free)
{
    rbtree_t *t = rb_malloc(sizeof *t);
    if (t == NULL) {
        return NULL;
    }
    t->value_free = value_free;
    t->count = 0;
    return t;
}

int rb_insert(rbtree_t *t, const char *key, void *value)
{
    (void)t;
    (void)key;
    (void)value;
    return -1;                  /* M1 */
}

void *rb_find(const rbtree_t *t, const char *key)
{
    (void)t;
    (void)key;
    return NULL;                /* M1 */
}

int rb_delete(rbtree_t *t, const char *key)
{
    (void)t;
    (void)key;
    return -1;                  /* M2 */
}

size_t rb_size(const rbtree_t *t)
{
    return (t == NULL) ? 0 : t->count;
}

void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx)
{
    (void)t;
    (void)fn;
    (void)ctx;                  /* M1 */
}

/* WARNING: this stub is a lying oracle. It reports "valid" unconditionally,
 * so until M1 replaces it, every test that trusts rb_validate passes for
 * free. Implement it with the first real insert, not after. */
int rb_validate(const rbtree_t *t)
{
    (void)t;
    return 0;                   /* M1 */
}

void rb_destroy(rbtree_t *t)
{
    if (t == NULL) {
        return;                 /* the header promises NULL-safety */
    }
    rb_free(t);
}
EOF

cat > tests/test_rbtree.c <<'EOF'
