{
    (void)t;
    return 0;                   /* M1 */
}
"""
new_validate = """/* In-order walk of one subtree. *prev is the last key seen so far (NULL
 * before the first); every key must be strictly greater than it. *count
 * accumulates the real number of nodes. Returns 0 or the first broken rule. */
static int validate_subtree(const struct rbnode *n, const char **prev,
                            size_t *count)
{
    if (n == NULL) {
        return RB_OK;
    }

    if (n->left != NULL && n->left->parent != n) {
        return RB_BAD_PARENT;
    }
    if (n->right != NULL && n->right->parent != n) {
        return RB_BAD_PARENT;
    }

    int rc = validate_subtree(n->left, prev, count);
    if (rc != RB_OK) {
        return rc;
    }

    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
        return RB_BAD_ORDER;
    }
